import type { PageItem, PaginationContextType } from "../pagination.types";

import {
  useMemo,
  useState,
  useCallback,
  useEffect,
  useContext,
  createContext,
  useRef,
} from "react";

const MINIMUM_SPREAD = 5;

export const PaginationContext = createContext<PaginationContextType | undefined>(undefined);
export const usePaginationContext = () => {
  const context = useContext(PaginationContext);
  if (context === undefined) {
    throw new Error("usePaginationContext must be used within a PaginationProvider");
  }
  return context;
};

const range = (start: number, finish: number): PageItem[] => {
  return Array.from({ length: finish - start + 1 }, (_, i) => ({ type: "page", value: start + i }));
};
export const usePagination = (
  start: number,
  finish: number,
  spread: number,
  selected: number,
  onSelectedChange?: (selected: number) => void,
) => {
  const [selectedIndex, setSelectedIndex] = useState(selected);
  const isMounted = useRef(false);

  const selectIndex = useCallback(
    (index: number) => {
      setSelectedIndex(index);
      onSelectedChange?.(index);
    },
    [onSelectedChange],
  );

  useEffect(() => {
    if (isMounted.current) {
      setSelectedIndex(selected);
    } else {
      isMounted.current = true;
      setSelectedIndex(selected);
    }
  }, [selected]);

  const items = useMemo(() => {
    if (finish < start) {
      // eslint-disable-next-line react-hooks/exhaustive-deps
      finish = start;
    }

    const validSpread = Math.max(spread, MINIMUM_SPREAD);
    const totalIndices = finish - start + 1;

    if (totalIndices <= validSpread) {
      return range(start, finish);
    }

    const result: PageItem[] = [];
    const innerSpread = validSpread - 2;

    result.push({ type: "page", value: start });

    const evenAdjuster = 1 - (innerSpread % 2);
    const leftSpread = Math.floor(innerSpread / 2) - evenAdjuster;
    const rightSpread = Math.floor(innerSpread / 2);

    let rangeEnd = selectedIndex + rightSpread;
    let rangeStart = selectedIndex - leftSpread;
    let rangeAdjust = 0;

    if (rangeEnd > finish - 1) {
      rangeAdjust = finish - 1 - rangeEnd;
    } else if (rangeStart < start + 1) {
      rangeAdjust = start + 1 - rangeStart;
    }

    rangeStart += rangeAdjust;
    rangeEnd += rangeAdjust;

    if (rangeStart === start + 1) {
      result.push({ type: "page", value: start + 1 });
    } else {
      result.push({ type: "ellipsis" });
    }

    result.push(...range(rangeStart + 1, rangeEnd - 1));

    if (rangeEnd === finish - 1) {
      result.push({ type: "page", value: rangeEnd });
    } else {
      result.push({ type: "ellipsis" });
    }

    result.push({ type: "page", value: finish });

    return result;
  }, [start, finish, spread, selectedIndex]);

  return {
    items,
    selectedIndex,
    selectIndex,
    start,
    finish,
    spread,
  };
};
